import{_ as n,o as r,c as s,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const h=JSON.parse('{"title":"Mahnungsdruck über den Gruppenprozess vorbereiten","description":"","frontmatter":{"title":"Mahnungsdruck über den Gruppenprozess vorbereiten","source_pageid":1542,"source_revision":6301},"headers":[],"relativePath":"reporting/zeugnisformulare/mahnungsdruck-einleiten-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"reporting/zeugnisformulare/mahnungsdruck-einleiten-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),i={name:"reporting/zeugnisformulare/mahnungsdruck-einleiten-gruppenprozesse-noten-zeugnisvorbereitung.md"};function u(o,e,p,a,d,g){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="mahnungsdruck-uber-den-gruppenprozess-vorbereiten" tabindex="-1">Mahnungsdruck über den Gruppenprozess vorbereiten <a class="header-anchor" href="#mahnungsdruck-uber-den-gruppenprozess-vorbereiten" aria-label="Permalink to &quot;Mahnungsdruck über den Gruppenprozess vorbereiten&quot;">​</a></h1><p>Der Gruppenprozess bereitet die Schülerauswahl und die Mahndaten für Mahnbriefe und Übersichtslisten vor. Der eigentliche Ausdruck erfolgt anschließend mit den passenden Reports.</p><p><strong>Den Gruppenprozess aufrufen</strong></p><p>Öffnen Sie <strong>Gruppenprozesse → Noten/Zeugnisvorbereitung → Mahnungsdruck einleiten</strong>. Der Prozess unterstützt Mahnschreiben an Erziehungsberechtigte und die zugehörigen Übersichtslisten.</p><p>Die Abläufe zum Setzen der Mahndaten und zum Drucken der weiterentwickelten Mahnberichte sind aufeinander abgestimmt. Verwenden Sie deshalb die vollständige Anleitung <a href="/reporting/reportdesigner/mahnbriefe-drucken-tutorial.html">Mahnbriefe drucken</a>, bevor Sie den Gruppenprozess mit den zugehörigen Reports einsetzen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Mahnungsdruck_einleiten_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6301.</p>',7)])])}const c=n(i,[["render",u]]);export{h as __pageData,c as default};
